CREATE TABLE sys_org_unit (id bigserial PRIMARY KEY, parent_id bigint REFERENCES sys_org_unit(id), name varchar(100) NOT NULL, type varchar(20) NOT NULL CHECK(type IN ('COMPANY','DEPARTMENT','TEAM')), sort_order int NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_user (id bigserial PRIMARY KEY, username varchar(64) UNIQUE NOT NULL, password_hash varchar(255) NOT NULL, display_name varchar(100) NOT NULL, org_unit_id bigint REFERENCES sys_org_unit(id), must_change_password boolean NOT NULL DEFAULT true, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','DISABLED','LOCKED')), failed_login_count int NOT NULL DEFAULT 0, locked_until timestamptz, last_login_at timestamptz, session_version int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_role (id bigserial PRIMARY KEY, role_code varchar(64) UNIQUE NOT NULL, role_name varchar(100) NOT NULL, description varchar(255), enabled boolean NOT NULL DEFAULT true, system_role boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_user_role (user_id bigint REFERENCES sys_user(id) ON DELETE CASCADE, role_id bigint REFERENCES sys_role(id), PRIMARY KEY(user_id,role_id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_module (id bigserial PRIMARY KEY, module_code varchar(64) UNIQUE NOT NULL, name varchar(100) NOT NULL, version varchar(32), status varchar(20) NOT NULL DEFAULT 'ONLINE', registered_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_menu (id bigserial PRIMARY KEY, module_id bigint NOT NULL REFERENCES sys_module(id), parent_id bigint REFERENCES sys_menu(id), menu_code varchar(100) UNIQUE NOT NULL, name varchar(100) NOT NULL, route_path varchar(200), component_key varchar(200), icon varchar(64), sort_order int NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, technical_hash varchar(64), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_role_menu (role_id bigint REFERENCES sys_role(id) ON DELETE CASCADE, menu_id bigint REFERENCES sys_menu(id), PRIMARY KEY(role_id,menu_id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_login_log (id bigserial PRIMARY KEY, user_id bigint REFERENCES sys_user(id), username varchar(64) NOT NULL, success boolean NOT NULL, reason varchar(100), ip varchar(64), user_agent varchar(500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_audit_log (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES sys_user(id), module varchar(64) NOT NULL, action varchar(64) NOT NULL, target_type varchar(64), target_id varchar(128), request_id varchar(64) NOT NULL, request_summary jsonb, before_data jsonb, after_data jsonb, success boolean NOT NULL, duration_ms int, ip varchar(64), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dim_market (market_code varchar(16) PRIMARY KEY, market_name varchar(100) NOT NULL, currency_code varchar(8) NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dim_shop (id bigserial PRIMARY KEY, market_code varchar(16) NOT NULL REFERENCES dim_market(market_code), shop_key varchar(100) NOT NULL, shop_name varchar(200) NOT NULL, enabled boolean NOT NULL DEFAULT true, UNIQUE(market_code,shop_key), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_import_task (id bigserial PRIMARY KEY, source_type varchar(32) NOT NULL, market_code varchar(16) NOT NULL REFERENCES dim_market(market_code), shop_id bigint NOT NULL REFERENCES dim_shop(id), biz_date_from date, biz_date_to date, original_filename varchar(255) NOT NULL, stored_path varchar(500) NOT NULL, file_hash varchar(64) NOT NULL, header_signature varchar(64), status varchar(32) NOT NULL, total_rows int NOT NULL DEFAULT 0, success_rows int NOT NULL DEFAULT 0, failed_rows int NOT NULL DEFAULT 0, created_by bigint NOT NULL REFERENCES sys_user(id), started_at timestamptz, finished_at timestamptz, error_message text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sys_import_error (id bigserial PRIMARY KEY, task_id bigint NOT NULL REFERENCES sys_import_task(id), row_no int, field_name varchar(100), raw_value text, error_code varchar(64) NOT NULL, message varchar(500) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fact_shop_daily (id bigserial PRIMARY KEY, shop_id bigint NOT NULL REFERENCES dim_shop(id), market_code varchar(16) NOT NULL REFERENCES dim_market(market_code), biz_date date NOT NULL, currency_code varchar(8) NOT NULL, gmv numeric(18,2) NOT NULL DEFAULT 0, order_count bigint NOT NULL DEFAULT 0, sold_qty bigint NOT NULL DEFAULT 0, visitor_count bigint, conversion_rate_src numeric(10,6), UNIQUE(shop_id,biz_date), raw_extra jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fact_product_daily (id bigserial PRIMARY KEY, shop_id bigint NOT NULL REFERENCES dim_shop(id), market_code varchar(16) NOT NULL REFERENCES dim_market(market_code), biz_date date NOT NULL, currency_code varchar(8) NOT NULL, product_id varchar(64) NOT NULL, gmv numeric(18,2) NOT NULL DEFAULT 0, order_count bigint NOT NULL DEFAULT 0, sku_order_count bigint NOT NULL DEFAULT 0, sold_qty bigint NOT NULL DEFAULT 0, estimated_customer_count bigint NOT NULL DEFAULT 0, impressions bigint NOT NULL DEFAULT 0, clicks bigint NOT NULL DEFAULT 0, add_to_cart_count bigint NOT NULL DEFAULT 0, refund_amount numeric(18,2) NOT NULL DEFAULT 0, refunded_qty bigint NOT NULL DEFAULT 0, refund_customer_count bigint NOT NULL DEFAULT 0, unique_impressions bigint, unique_clicks bigint, added_user_count bigint, UNIQUE(shop_id,biz_date,product_id), raw_extra jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fact_order (id bigserial PRIMARY KEY, shop_id bigint NOT NULL REFERENCES dim_shop(id), market_code varchar(16) NOT NULL REFERENCES dim_market(market_code), biz_date date NOT NULL, currency_code varchar(8) NOT NULL, order_id varchar(100) NOT NULL, source_status varchar(100), normalized_status varchar(32) NOT NULL, order_amount numeric(18,2) NOT NULL DEFAULT 0, item_qty bigint NOT NULL DEFAULT 0, order_created_at timestamptz, UNIQUE(shop_id,order_id), raw_extra jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fact_ad_campaign_daily (id bigserial PRIMARY KEY, shop_id bigint NOT NULL REFERENCES dim_shop(id), market_code varchar(16) NOT NULL REFERENCES dim_market(market_code), biz_date date NOT NULL, currency_code varchar(8) NOT NULL, ad_account_key varchar(100) NOT NULL DEFAULT 'default', campaign_id varchar(100) NOT NULL, campaign_name varchar(255), spend numeric(18,2) NOT NULL DEFAULT 0, attributed_revenue numeric(18,2) NOT NULL DEFAULT 0, attributed_order_count bigint NOT NULL DEFAULT 0, impressions bigint, clicks bigint, UNIQUE(shop_id,biz_date,ad_account_key,campaign_id), raw_extra jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fact_refund_detail (id bigserial PRIMARY KEY, shop_id bigint NOT NULL REFERENCES dim_shop(id), market_code varchar(16) NOT NULL REFERENCES dim_market(market_code), biz_date date NOT NULL, currency_code varchar(8) NOT NULL, refund_id varchar(100) NOT NULL, order_id varchar(100), refund_amount numeric(18,2), refund_qty bigint, refund_status varchar(64), refund_time timestamptz, UNIQUE(shop_id,refund_id), raw_extra jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agg_dashboard_daily (shop_id bigint NOT NULL REFERENCES dim_shop(id), market_code varchar(16) NOT NULL, biz_date date NOT NULL, currency_code varchar(8) NOT NULL, gmv numeric(18,2) NOT NULL DEFAULT 0, refund_amount numeric(18,2) NOT NULL DEFAULT 0, ad_spend numeric(18,2) NOT NULL DEFAULT 0, ad_revenue numeric(18,2) NOT NULL DEFAULT 0, order_count bigint NOT NULL DEFAULT 0, sold_qty bigint NOT NULL DEFAULT 0, sku_order_count bigint NOT NULL DEFAULT 0, refunded_qty bigint NOT NULL DEFAULT 0, refund_customer_count bigint NOT NULL DEFAULT 0, ad_order_count bigint NOT NULL DEFAULT 0, cancel_order_count bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(shop_id,market_code,biz_date));
CREATE INDEX idx_order_market_date_status ON fact_order(market_code,biz_date,normalized_status);
CREATE INDEX idx_order_shop_date ON fact_order(shop_id,biz_date);
CREATE INDEX idx_product_market_date ON fact_product_daily(market_code,biz_date);
CREATE INDEX idx_ad_market_date ON fact_ad_campaign_daily(market_code,biz_date);
CREATE INDEX idx_audit_user_time ON sys_audit_log(user_id,created_at DESC);
CREATE INDEX idx_login_time ON sys_login_log(created_at DESC);
CREATE INDEX idx_import_hash ON sys_import_task(shop_id,source_type,file_hash);
CREATE INDEX idx_import_error_task ON sys_import_error(task_id,id);
CREATE UNIQUE INDEX idx_import_active ON sys_import_task(shop_id,source_type) WHERE status IN ('CREATED','VALIDATING','IMPORTING','AGGREGATING');
